/bin/bash -lc "cat > /tmp/screenshot.mjs <<'EOF'
import { chromium } from 'playwright-core';
import fs from 'fs';
const browser = await chromium.launch();
for (const theme of ['light', 'dark']) {
  const page = await browser.newPage({ viewport: { width: 900, height: 600 } });
  await page.goto('http://127.0.0.1:4173/');
  await page.waitForTimeout(1000);
  await page.evaluate((nextTheme) => {
    document.body.className = "'`g-root g-root_theme_${nextTheme}`;
  }, theme);
  await page.waitForTimeout(1200);
  const info = await page.evaluate(() => {
    const svg = document.querySelector('"'svg');
    const path = svg?.querySelector('path[stroke]');
    const tick = svg?.querySelector('.gcharts-x-axis__tick');
    const label = svg?.querySelector('.gcharts-x-axis__label');
    return {
      bodyClass: document.body.className,
      svgCount: document.querySelectorAll('svg').length,
      pathCount: svg?.querySelectorAll('path').length,
      stroke: path ? path.getAttribute('stroke') : null,
      tickStroke: tick ? getComputedStyle(tick).stroke : null,
      labelFill: label ? getComputedStyle(label).fill : null,
      bodyBackground: getComputedStyle(document.body).backgroundColor,
      mainBackground: getComputedStyle(document.querySelector('main')).backgroundColor,
      titleText: [...svg?.querySelectorAll('text') ?? []].map((node) => node.textContent).filter(Boolean).slice(0, 12),
      legendSymbol: svg?.querySelector('.gcharts-legend__item-symbol_shape_path')?.getAttribute('stroke'),
    };
  });
  console.log(theme, JSON.stringify(info, null, 2));
  await page.screenshot({ path: "'`/tmp/chart-${theme}.png` });
  await page.close();
}
await browser.close();
EOF
node /tmp/screenshot.mjs'

/bin/bash -lc "cat > debug-browser.mjs <<'EOF'
