/bin/bash -lc "cat > debug-browser-verbose.mjs <<'EOF'
import { chromium } from 'playwright-core';
const browser = await chromium.launch({ logger: { isEnabled: () => true, log: (name, severity, message) => console.error(name, severity, message) } });
const page = await browser.newPage();
page.on('console', m => console.log('console', m.type(), m.text()));
page.on('pageerror', e => console.error('pageerror', e));
try {
  await page.goto('http://127.0.0.1:4173/', {waitUntil:'commit', timeout:10000});
  console.log('committed');
  await page.waitForTimeout(5000);
} catch (error) {
  console.error('goto error', error);
}
console.log('closing');
await browser.close();
EOF
LD_LIBRARY_PATH="'$PWD/.chrome-libs/usr/lib/aarch64-linux-gnu:$PWD/.chrome-libs/lib/aarch64-linux-gnu node debug-browser-verbose.mjs'

/bin/bash -lc "cat > debug-browser-crash.mjs <<'EOF'
import { chromium } from 'playwright-core';
const browser = await chromium.launch({ timeout: 20000 });
try {
  const context = await browser.newContext();
  const page = await context.newPage();
  await page.goto('http://127.0.0.1:4173/', {waitUntil:'commit', timeout:10000});
  console.log('committed');
  await page.waitForLoadState('load', { timeout: 10000 });
  console.log('loaded');
} catch (error) {
  console.error(error);
}
await browser.close();
EOF
